sys_script_include.script:
/** @type {MarkdownGenerationContextConstructor} */
var MarkdownGenerationContext = (function() {
    var instanceUri = gs.getProperty('glide.servlet.uri');

    /** @type {MarkdownGenerationContextConstructor} */
    var MarkdownGenerationContextConstructor = Class.create();

    /**
     * @param {string} [path]
     * @return {string}
     */
    function getInstanceUrl(path) {
        if (gs.nil(path))
            return instanceUri;
        var p = '' + path;
        while (p.startsWith('/') || p.startsWith('\\'))
            p = p.substring(1);
        return instanceUri + p;
    }

    MarkdownGenerationContextConstructor.getInstanceUrl = getInstanceUrl;

    /**
     * @param {string} id 
     * @returns {GlideRecordSecure}
     */
    function getTableFromId(id) {
        var gr = new GlideRecordSecure('sys_db_object');
        if (!gr.get(id)) {
            gr = new GlideRecordSecure('sys_db_object');
            gr.addQuery('name', id);
            gr.query();
            if (!gr.next())
                throw new Error("Cannot find Table with name or Sys ID of " + JSON.stringify(id));
        }
        return gr;
    }

    MarkdownGenerationContextConstructor.getTableFromId = getTableFromId;

    /**
     * @param {string} sysID 
     * @returns {GlideRecordSecure}
     */
    function getCatalogItemFromSysId(sysID) {
        var gr = new GlideRecordSecure('sc_cat_item');
        if (!gr.get(sysID))
            throw new Error("Cannot find Catalog Item with Sys ID of " + JSON.stringify(sysID));
        return gr;
    }

    MarkdownGenerationContextConstructor.getCatalogItemFromSysId = getCatalogItemFromSysId;

    /**
     * @param {string} id 
     * @returns {GlideRecordSecure}
     */
    function getVariableSetFromId(id) {
        var gr = new GlideRecordSecure('item_option_new_set');
        if (!gr.get(id)) {
            gr = new GlideRecordSecure('item_option_new_set');
            gr.addQuery('internal_name', id);
            gr.query();
            if (!gr.next())
                throw new Error("Cannot find Variable Set with internal name or Sys ID of " + JSON.stringify(id));
        }
        return gr;
    }

    MarkdownGenerationContextConstructor.getVariableSetFromId = getVariableSetFromId;

    /**
     * @param {string} id 
     * @returns {GlideRecordSecure}
     */
    function getFlowFromId(id) {
        var gr = new GlideRecordSecure('sys_hub_flow');
        if (!gr.get(id)) {
            gr = new GlideRecordSecure('sys_hub_flow');
            gr.addQuery('internal_name', id);
            gr.query();
            if (!gr.next())
                throw new Error("Cannot find Flow with internal name or Sys ID of " + JSON.stringify(id));
        }
        return gr;
    }

    MarkdownGenerationContextConstructor.getFlowFromId = getFlowFromId;

    var markdownReservedRe = /[\\`*[\]()]/g;
    var markdownLeadReservedRe = /^[#|]/;
    var markdownTableReservedRe = /[\\`*[\]()|]/g;
    var newLineRe = /\n/g;
    var codeBlockReqRe = /[\n`]/g;

    /**
     * @param {string} text
     * @param {boolean} [isTableCellContent]
     * @returns {string}
     */
    function escapeForMarkdown(text, isTableCellContent) {
        return isTableCellContent ? text.replace(markdownTableReservedRe, '\\$&') : text.replace(markdownReservedRe, '\\$&').replace(markdownLeadReservedRe, '\\$&');
    }

    MarkdownGenerationContextConstructor.escapeForMarkdown = escapeForMarkdown;

    MarkdownGenerationContextConstructor.prototype = {
        _tableUrls: {},

        _catalogItemUrls: {},

        _variableSetUrls: {},

        _flowUrls: {},

        initialize: function() {},

        addTableUrl: function(id, url) {
            var gr = getTableFromId(id);
            if (!gs.nil(gr.name))
                this._tableUrls[gr.getValue('name')] = url;
            this._tableUrls[gr.getValue('sys_id')] = url;
        },

        getTableUrl: function(table) {
            if (gs.nil(table))
                return;
            var link;
            if (table instanceof GlideRecord || table instanceof GlideRecordSecure) {
                link = this._tableUrls[table.getUniqueValue()];
                if (typeof link !== 'undefined')
                    return link;
            } else {
                var id = '' + table;
                link = this._tableUrls[id];
                if (typeof link !== 'undefined')
                    return link;
            }
        },

        getTableMdLink: function(table, isTableCellContent) {
            if (gs.nil(table))
                return '*null*';
            var link;
            if (table instanceof GlideRecord || table instanceof GlideRecordSecure) {
                link = this._tableUrls[table.getUniqueValue()];
                if (typeof link !== 'undefined')
                    return "[" + escapeForMarkdown(table.getValue(gs.nil(table.label) ? 'name' : 'label'), isTableCellContent) + "](" + link + ")";
                return "[" + escapeForMarkdown(table.getValue(gs.nil(table.label) ? 'name' : 'label'), isTableCellContent) + "](" + instanceUri + table.getLink(true) + ")";
            }
            var gr = getTableFromId(table);
            link = this._tableUrls[gr.getUniqueValue()];
            if (typeof link !== 'undefined')
                return "[" + escapeForMarkdown(gr.getValue(gs.nil(gr.label) ? 'name' : 'label'), isTableCellContent) + "](" + link + ")";
            return "[" + escapeForMarkdown(gr.getValue(gs.nil(gr.label) ? 'name' : 'label'), isTableCellContent) + "](" + instanceUri + gr.getLink(true) + ")";
        },

        addCatalogItemUrl: function(sysID, url) {
            this._catalogItemUrls[getCatalogItemFromSysId(id).getUniqueValue()] = url;
        },

        getCatalogItemUrl: function(catalogItem) {
            if (gs.nil(catalogItem))
                return;
            var link;
            if (catalogItem instanceof GlideRecord || catalogItem instanceof GlideRecordSecure) {
                link = this._catalogItemUrls[catalogItem.getUniqueValue()];
                if (typeof link !== 'undefined')
                    return link;
            } else {
                var id = '' + catalogItem;
                link = this._catalogItemUrls[id];
                if (typeof link !== 'undefined')
                    return link;
            }
        },

        getCatalogItemMdLink: function(catalogItem, isTableCellContent) {
            if (gs.nil(catalogItem))
                return '*null*';
            var link;
            if (catalogItem instanceof GlideRecord || catalogItem instanceof GlideRecordSecure) {
                link = this._catalogItemUrls[catalogItem.getUniqueValue()];
                if (typeof link !== 'undefined')
                    return "[" + escapeForMarkdown(catalogItem.getValue('name'), isTableCellContent) + "](" + link + ")";
                return "[" + escapeForMarkdown(catalogItem.getValue('name'), isTableCellContent) + "](" + instanceUri + catalogItem.getLink(true) + ")";
            }
            var gr = getCatalogItemFromSysId(catalogItem);
            link = this._catalogItemUrls[gr.getUniqueValue()];
            if (typeof link !== 'undefined')
                return "[" + escapeForMarkdown(gr.getValue('name'), isTableCellContent) + "](" + link + ")";
            return "[" + escapeForMarkdown(gr.getValue('name'), isTableCellContent) + "](" + instanceUri + gr.getLink(true) + ")";
        },

        addVariableSetUrl: function(id, url) {
            var gr = getVariableSetFromId(id);
            if (!gs.nil(gr.internal_name))
                this._variableSetUrls[gr.getValue('internal_name')] = url;
            this._variableSetUrls[gr.getValue('sys_id')] = url;
        },

        getVariableSetUrl: function(variableSet) {
            if (gs.nil(variableSet))
                return;
            var link;
            if (variableSet instanceof GlideRecord || variableSet instanceof GlideRecordSecure) {
                link = this._variableSetUrls[variableSet.getUniqueValue()];
                if (typeof link !== 'undefined')
                    return link;
            } else {
                var id = '' + variableSet;
                link = this._variableSetUrls[id];
                if (typeof link !== 'undefined')
                    return link;
            }
        },

        getVariableSetMdLink: function(variableSet, isTableCellContent) {
            if (gs.nil(variableSet))
                return '*null*';
            var link;
            if (variableSet instanceof GlideRecord || variableSet instanceof GlideRecordSecure) {
                link = this._variableSetUrls[variableSet.getUniqueValue()];
                if (typeof link !== 'undefined')
                    return "[" + escapeForMarkdown(variableSet.getValue(gs.nil(variableSet.title) ? 'internal_name' : 'title'), isTableCellContent) + "](" + link + ")";
                return "[" + escapeForMarkdown(variableSet.getValue(gs.nil(variableSet.title) ? 'internal_name' : 'title'), isTableCellContent) + "](" + instanceUri + variableSet.getLink(true) + ")";
            }
            var gr = getVariableSetFromId(variableSet);
            link = this._variableSetUrls[gr.getUniqueValue()];
            if (typeof link !== 'undefined')
                return "[" + escapeForMarkdown(gr.getValue(gs.nil(gr.title) ? 'internal_name' : 'title'), isTableCellContent) + "](" + link + ")";
            return "[" + escapeForMarkdown(gr.getValue(gs.nil(gr.title) ? 'internal_name' : 'title'), isTableCellContent) + "](" + instanceUri + gr.getLink(true) + ")";
        },

        addFlowUrl: function(id, url) {
            var gr = getFlowFromId(id);
            if (!gs.nil(gr.internal_name))
                this._flowUrls[gr.getValue('internal_name')] = url;
            this._flowUrls[gr.getValue('sys_id')] = url;
        },

        getFlowUrl: function(flow) {
            if (gs.nil(flow))
                return;
            var link;
            if (flow instanceof GlideRecord || flow instanceof GlideRecordSecure) {
                link = this._flowUrls[flow.getUniqueValue()];
                if (typeof link !== 'undefined')
                    return link;
            } else {
                var id = '' + flow;
                link = this._flowUrls[id];
                if (typeof link !== 'undefined')
                    return link;
            }
        },

        getFlowMdLink: function(flow, isTableCellContent) {
            if (gs.nil(flow))
                return '*null*';
            var link;
            if (flow instanceof GlideRecord || flow instanceof GlideRecordSecure) {
                link = this._flowUrls[flow.getUniqueValue()];
                if (typeof link !== 'undefined')
                    return "[" + escapeForMarkdown(flow.getValue(gs.nil(flow.title) ? 'internal_name' : 'name'), isTableCellContent) + "](" + link + ")";
                return "[" + escapeForMarkdown(flow.getValue(gs.nil(flow.title) ? 'internal_name' : 'name'), isTableCellContent) + "](" + instanceUri + flow.getLink(true) + ")";
            }
            var gr = getFlowFromId(flow);
            link = this._flowUrls[gr.getUniqueValue()];
            if (typeof link !== 'undefined')
                return "[" + escapeForMarkdown(gr.getValue(gs.nil(gr.title) ? 'internal_name' : 'name'), isTableCellContent) + "](" + link + ")";
            return "[" + escapeForMarkdown(gr.getValue(gs.nil(gr.title) ? 'internal_name' : 'name'), isTableCellContent) + "](" + instanceUri + gr.getLink(true) + ")";
        },

        type: 'MarkdownGenerationContext'
    };

    return MarkdownGenerationContextConstructor;
})();
